// src/pages/logs/LogsPage.jsx
import React, { useMemo, useState } from 'react';
import { useLogs } from '../../hooks/UseLogs';
import { deleteLog, deleteLogs } from '../../api/LogsApi';
import LogFilterBar from '../../components/logs/LogFilterBar';
import LogTable from '../../components/logs/LogTable';
import LogDetailModal from '../../components/logs/LogDetailModal';

function toCsv(rows) {
  const headers = [
    'id',
    'collectedAt',
    'eventType',
    'path',
    'exists',
    'size',
    'entropy',
    'aiLabel',
    'aiScore',
    'aiDetail',
  ];

  const esc = (v) => {
    const s = v == null ? '' : String(v);
    const needs = /[",\n]/.test(s);
    const out = s.replaceAll('"', '""');
    return needs ? `"${out}"` : out;
  };

  const lines = [];
  lines.push(headers.join(','));
  for (const r of rows) {
    const line = headers.map((h) => esc(r?.[h]));
    lines.push(line.join(','));
  }
  return lines.join('\n');
}

function download(content, filename, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function parseDateYmd(s) {
  // collectedAt이 "2025-12-15T..." 또는 "2025-12-15 ..." 등일 수 있어서 앞 10글자만 사용
  if (!s) return null;
  const ymd = String(s).slice(0, 10);
  const t = Date.parse(ymd);
  return Number.isFinite(t) ? t : null;
}

function LogsPage() {
  const {
    logs,
    loading,
    error,
    page,
    setPage,
    size,
    setSize,
    total,
    filters,
    setFilters,
    refresh,
    search,
  } = useLogs(50);

  // UI용 위험도 필터(UNKNOWN 포함)
  const [riskFilter, setRiskFilter] = useState('ALL'); // ALL|DANGER|WARNING|SAFE|UNKNOWN
  const [selectedLog, setSelectedLog] = useState(null);

  const filteredLogs = useMemo(() => {
    const kw = String(filters.keyword || '').trim().toLowerCase();
    const fromT = filters.from ? Date.parse(filters.from) : null;
    const toT = filters.to ? Date.parse(filters.to) : null;

    return (Array.isArray(logs) ? logs : []).filter((l) => {
      const label = String(l.aiLabel || '').toUpperCase();

      // keyword
      const matchKeyword =
        !kw ||
        String(l.path || '').toLowerCase().includes(kw) ||
        String(l.eventType || '').toLowerCase().includes(kw) ||
        String(l.aiDetail || '').toLowerCase().includes(kw) ||
        String(l.aiLabel || '').toLowerCase().includes(kw);

      // risk
      let matchRisk = true;
      if (riskFilter === 'DANGER') matchRisk = label === 'DANGER';
      else if (riskFilter === 'WARNING') matchRisk = label === 'WARNING';
      else if (riskFilter === 'SAFE') matchRisk = label === 'SAFE';
      else if (riskFilter === 'UNKNOWN') matchRisk = !label;

      // date range (fallback일 때도 동작)
      let matchDate = true;
      if (fromT || toT) {
        const t = parseDateYmd(l.collectedAt);
        if (t == null) {
          matchDate = true; // 파싱 불가면 일단 통과
        } else {
          if (fromT && t < fromT) matchDate = false;
          if (toT && t > toT) matchDate = false;
        }
      }

      return matchKeyword && matchRisk && matchDate;
    });
  }, [logs, filters.keyword, filters.from, filters.to, riskFilter]);

  const handleDeleteOne = async (id) => {
    const ok = window.confirm(`이 로그(ID: ${id})를 삭제할까요?`);
    if (!ok) return;

    try {
      await deleteLog(id);
      if (selectedLog?.id === id) setSelectedLog(null);
      await refresh();
    } catch (e) {
      alert(`삭제 실패(백엔드 미구현/에러 가능): ${String(e.message || e)}`);
    }
  };

  const handleDeleteSelected = async (ids) => {
    if (!ids || ids.length === 0) return;
    const ok = window.confirm(`선택한 로그 ${ids.length}개를 삭제할까요?`);
    if (!ok) return;

    try {
      await deleteLogs(ids);
      setSelectedLog(null);
      await refresh();
    } catch (e) {
      alert(`선택 삭제 실패(백엔드 미구현/에러 가능): ${String(e.message || e)}`);
    }
  };

  const handleExport = async (format, ids) => {
    const picked = filteredLogs.filter((l) => ids.includes(l.id));
    if (picked.length === 0) return;

    if (format === 'JSON') {
      download(JSON.stringify(picked, null, 2), `logs_selected_${Date.now()}.json`, 'application/json');
      return;
    }
    if (format === 'CSV') {
      download(toCsv(picked), `logs_selected_${Date.now()}.csv`, 'text/csv');
    }
  };

  const handleExportAll = async (format) => {
    const rows = filteredLogs;
    if (!rows || rows.length === 0) return;

    if (format === 'JSON') {
      download(JSON.stringify(rows, null, 2), `logs_all_${Date.now()}.json`, 'application/json');
      return;
    }
    if (format === 'CSV') {
      download(toCsv(rows), `logs_all_${Date.now()}.csv`, 'text/csv');
    }
  };

  const totalPages = useMemo(() => {
    if (total == null) return null;
    return Math.max(1, Math.ceil(Number(total || 0) / Math.max(1, Number(size || 1))));
  }, [total, size]);

  return (
    <div className="page-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
        <h1>로그 관리(=감시 이벤트)</h1>

        <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          size
          <select value={size} onChange={(e) => { setSize(Number(e.target.value)); setPage(1); }}>
            <option value={10}>10</option>
            <option value={20}>20</option>
            <option value={50}>50</option>
            <option value={100}>100</option>
          </select>
        </label>
      </div>

      <LogFilterBar
        keyword={filters.keyword}
        setKeyword={(v) => setFilters((prev) => ({ ...prev, keyword: v }))}

        riskFilter={riskFilter}
        setRiskFilter={(v) => {
          setRiskFilter(v);
          // 서버 필터(가능하면)도 같이 태움: UNKNOWN은 서버에 없어서 빈값 처리
          if (v === 'DANGER' || v === 'WARNING' || v === 'SAFE') {
            setFilters((prev) => ({ ...prev, aiLabel: v }));
          } else {
            setFilters((prev) => ({ ...prev, aiLabel: '' }));
          }
          setPage(1);
        }}

        from={filters.from}
        setFrom={(v) => { setFilters((prev) => ({ ...prev, from: v })); setPage(1); }}
        to={filters.to}
        setTo={(v) => { setFilters((prev) => ({ ...prev, to: v })); setPage(1); }}

        sort={filters.sort}
        setSort={(v) => { setFilters((prev) => ({ ...prev, sort: v })); setPage(1); }}

        onSearch={search}
        onRefresh={refresh}
      />

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>에러: {String(error.message || error)}</p>}

      {!loading && !error && (
        <>
          <p style={{ opacity: 0.8, marginTop: 8 }}>
            {totalPages ? (
              <>총 {total}건 / {page} / {totalPages}</>
            ) : (
              <>최근 {filteredLogs.length}건(서버 페이징 미구현 시 최근 로그만 표시)</>
            )}
          </p>

          <LogTable
            logs={filteredLogs}
            onRowClick={(log) => setSelectedLog(log)}
            onExport={handleExport}
            onExportAll={handleExportAll}
            onDeleteSelected={handleDeleteSelected}
            onDeleteOne={handleDeleteOne}
          />

          {totalPages && (
            <div style={{ display: 'flex', gap: 8, marginTop: 12, alignItems: 'center' }}>
              <button className="btn" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>
                이전
              </button>
              <span>
                {page} / {totalPages}
              </span>
              <button className="btn" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>
                다음
              </button>
            </div>
          )}
        </>
      )}

      <LogDetailModal
        log={selectedLog}
        onClose={() => setSelectedLog(null)}
        onDelete={async (log) => handleDeleteOne(log.id)}
      />
    </div>
  );
}

export default LogsPage;
